package org.novasos.healthysv2.maternalandchildhealth;
import static org.assertj.core.api.Assertions.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.novasos.healthysv2.TestcontainersConfiguration;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.context.annotation.Import;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;
@ActiveProfiles("test")@SpringBootTest@Import(TestcontainersConfiguration.class)@Transactional class MaternalChildRepositoryIntegrationTests{@Autowired PregnancyRepository pregnancies;@Autowired ChildHealthRecordRepository records;@Autowired JdbcTemplate jdbc;@Test void persistsPregnancyAndChildAggregates(){UUID mother=patient(),child=patient();var p=pregnancies.saveAndFlush(Pregnancy.start(mother,LocalDate.now().minusMonths(3),null,LocalDate.now().plusMonths(6)));p.addRisk("AGE","MODERATE",null);p.addVisit(null,null,Instant.now(),12,null,110,70,150,null);pregnancies.flush();var record=records.saveAndFlush(ChildHealthRecord.open(child,mother));record.addMeasurement(Instant.now(),java.math.BigDecimal.valueOf(4),java.math.BigDecimal.valueOf(55),null,null);records.flush();assertThat(pregnancies.findByMotherPatientIdOrderByCreatedAtDesc(mother)).hasSize(1);assertThat(records.findByChildPatientId(child)).isPresent();assertThat(jdbc.queryForObject("select count(*) from maternal_child.prenatal_visit where pregnancy_id=?",Integer.class,p.getId())).isEqualTo(1);}@Test void databaseRejectsEmptyGrowthMeasurements(){UUID child=patient();UUID record=UUID.randomUUID();jdbc.update("insert into maternal_child.child_health_record(id,child_patient_id) values (?,?)",record,child);assertThatThrownBy(()->jdbc.update("insert into maternal_child.growth_measurement(id,child_patient_id) values (?,?)",UUID.randomUUID(),child)).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);}private UUID patient(){UUID person=UUID.randomUUID(),patient=UUID.randomUUID();jdbc.update("insert into identity.person(id,person_number,first_name,last_name,status) values (?,?,?,?,?)",person,"PER-"+person,"Jane","Doe","ACTIVE");jdbc.update("insert into patient.patient(id,person_id,patient_number) values (?,?,?)",patient,person,"PAT-"+patient);return patient;}}
